#!/usr/bin/env node
/**
 * Bundle the Folia audio subsystem into one client fragment.
 *
 * The source of truth stays `A_other/upstream/folia-major-main/src/services/**`.
 * This script only compiles the boundary entry (`src/audio/entry.ts`); the
 * generated file is committed because `client.js` is a build product too.
 *
 *   node scripts/build-audio.mjs            # write src/client/audio/engine.bundle.js
 *   node scripts/build-audio.mjs --check    # fail if the bundle is stale
 */
import { build } from 'esbuild'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const OUT = join(ROOT, 'src/client/audio/engine.bundle.js')
const CHECK = process.argv.includes('--check')
const UPSTREAM_ENTRY = join(ROOT, 'A_other/upstream/folia-major-main/src/services/playbackGraph.ts')

// `A_other/upstream` is not part of the published package or a clean CI
// checkout. The generated bundle is committed, so --check only verifies that
// it exists there; it can only rebuild when the upstream source is present.
if (CHECK && !existsSync(UPSTREAM_ENTRY)) {
  if (!existsSync(OUT)) {
    console.error('src/client/audio/engine.bundle.js is missing and the upstream audio source is unavailable')
    process.exit(1)
  }
  console.log('audio bundle present (upstream source not checked out)')
  process.exit(0)
}

const result = await build({
  entryPoints: [join(ROOT, 'src/audio/entry.ts')],
  write: false,
  bundle: true,
  format: 'iife',
  globalName: 'MPAudio',
  platform: 'browser',
  target: ['chrome120'],
  minify: false,
  logLevel: 'silent',
  loader: { '.ts': 'ts' },
  plugins: [
    {
      name: 'audio-shims',
      setup(context) {
        // `crossfadeGraph` imports the stem registry and gesture constants. The
        // plugin ships no htdemucs, so the stem branches are wired to constants
        // instead of pulling the model and scheduler into the bundle.
        context.onResolve({ filter: /^\.\/stems$/ }, (args) => (
          args.importer.endsWith('crossfadeGraph.ts')
            ? { path: join(ROOT, 'src/audio/shims/stems.ts') }
            : null
        ))
        context.onResolve({ filter: /^\.\/stemGesture$/ }, (args) => (
          args.importer.endsWith('crossfadeGraph.ts')
            ? { path: join(ROOT, 'src/audio/shims/stemGesture.ts') }
            : null
        ))
        context.onResolve({ filter: /^\.\.\/stores\/useAudioSettingsStore$/ }, () => ({
          path: join(ROOT, 'src/audio/shims/useAudioSettingsStore.ts'),
        }))
      },
    },
  ],
  define: {
    'import.meta.env.DEV': 'false',
    'import.meta.env.PROD': 'true',
    'import.meta.env.MODE': '"production"',
    'import.meta.env.SSR': 'false',
  },
}).catch((error) => {
  const errors = error.errors || []
  console.error(`audio bundle failed: ${errors.length} error(s)`)
  for (const item of errors.slice(0, 40)) {
    const where = item.location
      ? `${item.location.file.replace(ROOT + '\\', '').replace(ROOT + '/', '')}:${item.location.line} `
      : ''
    console.error(`  ${where}${item.text}`)
  }
  if (errors.length === 0) console.error(String(error && error.message ? error.message : error))
  process.exit(1)
})

const text = result.outputFiles[0].text
const indented = text.replace(/\n/g, '\n  ')
const output = `/**
 * Folia audio subsystem — generated by scripts/build-audio.mjs.
 * Edit A_other/upstream/folia-major-main/src/services/** or src/audio/entry.ts,
 * then rebuild. Never edit this file by hand.
 */
function __mpAudioBundle() {
  ${indented}
  return typeof MPAudio === 'undefined' ? null : MPAudio
}
`

if (CHECK) {
  const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : ''
  if (current !== output) {
    console.error('src/client/audio/engine.bundle.js is stale; run node scripts/build-audio.mjs')
    process.exit(1)
  }
  console.log('audio bundle up to date')
} else {
  mkdirSync(dirname(OUT), { recursive: true })
  writeFileSync(OUT, output, 'utf8')
  console.log(`AUDIO BUNDLE OK bytes=${text.length}`)
}
